             </button>
             <div className="w-px bg-[#9D4EDD] mx-1 h-6 self-center opacity-50"></div>
             <button 
                onClick={() => setActiveTab('address-change')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'address-change' ? 'bg-[#5A189A] text-white shadow' : 'text-[#5A189A] hover:bg-[#E0C3FC]'}`}
             >
