  const [printData, setPrintData] = useState<ClientData[] | null>(null);
  const [pjPrintData, setPjPrintData] = useState<PJData[] | null>(null);
  const [addressChangePrintData, setAddressChangePrintData] = useState<AddressChangeData[] | null>(null);
  const [previewScale, setPreviewScale] = useState(0.75);

  // State to handle form resets and notifications
  const [formVersion, setFormVersion] = useState(0);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState("");

  const resetForm = useCallback(() => {
    setFormVersion(v => v + 1);
  }, []);

  const triggerSuccess = useCallback((message: string) => {
    setToastMessage(message);
    setShowToast(true);
    resetForm();
  }, [resetForm]);

  const handleGenerate = (data: ClientData | ClientData[]) => {
    const dataArray = Array.isArray(data) ? data : [data];
    setPrintData(dataArray);
    setPjPrintData(null);
    setAddressChangePrintData(null);

    setTimeout(() => {
      window.print();
      triggerSuccess("Documentos PF gerados com sucesso!");
    }, 100);
  };

  const handleGeneratePJ = (data: PJData | PJData[]) => {
    const dataArray = Array.isArray(data) ? data : [data];
    setPjPrintData(dataArray);
    setPrintData(null);
    setAddressChangePrintData(null);

    setTimeout(() => {
      window.print();
      triggerSuccess("Documentos PJ gerados com sucesso!");
    }, 100);
  };

  const handleGenerateAddressChange = (data: AddressChangeData | AddressChangeData[]) => {
    const dataArray = Array.isArray(data) ? data : [data];
    setAddressChangePrintData(dataArray);
    setPrintData(null);
    setPjPrintData(null);

    setTimeout(() => {
        window.print();
        triggerSuccess("Mudança de endereço gerada com sucesso!");
    }, 100);
  };

  return (
    <>
      <Toast 
        isVisible={showToast} 
        message={toastMessage} 
        onClose={() => setShowToast(false)} 
      />

      {/* Screen UI */}
      <div className="min-h-screen p-4 md:p-8 no-print bg-gray-50">
        <div className="max-w-7xl mx-auto">
          <header className="mb-8 border-b border-[#5A189A] pb-6">
            <h1 className="text-3xl font-bold text-black">DocuFlow Automation</h1>
            <p className="text-black opacity-80 mt-1">
              {activeTab.includes('pj') ? 'Módulo: Pessoa Jurídica (PJ)' : activeTab.includes('address') ? 'Módulo: Mudança de Endereço' : 'Módulo: Pessoa Física (PF)'}
            </p>
          </header>

          {/* Tabs */}
          <div className="flex flex-wrap gap-1 bg-[#F3E6FF] p-1 rounded-xl mb-6 w-fit border border-[#9D4EDD]">
             <button 
                onClick={() => setActiveTab('individual')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'individual' ? 'bg-[#5A189A] text-white shadow' : 'text-black hover:bg-[#E0C3FC]'}`}
             >
               <FileText className={`w-4 h-4 ${activeTab === 'individual' ? 'text-[#FF9000]' : 'text-black'}`} /> PF Individual
             </button>
             <button 
                onClick={() => setActiveTab('batch')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'batch' ? 'bg-[#5A189A] text-white shadow' : 'text-black hover:bg-[#E0C3FC]'}`}
             >
               <Layers className={`w-4 h-4 ${activeTab === 'batch' ? 'text-[#FF9000]' : 'text-black'}`} /> Lote PF
             </button>
             <div className="w-px bg-[#9D4EDD] mx-1 h-6 self-center opacity-50"></div>
             <button 
                onClick={() => setActiveTab('pj')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'pj' ? 'bg-[#5A189A] text-white shadow' : 'text-black hover:bg-[#E0C3FC]'}`}
             >
               <Building2 className={`w-4 h-4 ${activeTab === 'pj' ? 'text-[#FF9000]' : 'text-black'}`} /> PJ Individual
             </button>
             <button 
                onClick={() => setActiveTab('batch-pj')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'batch-pj' ? 'bg-[#5A189A] text-white shadow' : 'text-black hover:bg-[#E0C3FC]'}`}
             >
               <ListPlus className={`w-4 h-4 ${activeTab === 'batch-pj' ? 'text-[#FF9000]' : 'text-black'}`} /> Lote PJ
             </button>
             <div className="w-px bg-[#9D4EDD] mx-1 h-6 self-center opacity-50"></div>
             <button 
                onClick={() => setActiveTab('address-change')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'address-change' ? 'bg-[#5A189A] text-white shadow' : 'text-black hover:bg-[#E0C3FC]'}`}
             >
               <MapPin className={`w-4 h-4 ${activeTab === 'address-change' ? 'text-[#FF9000]' : 'text-black'}`} /> Mudança End.
             </button>
             <button 
                onClick={() => setActiveTab('batch-address-change')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'batch-address-change' ? 'bg-[#5A189A] text-white shadow' : 'text-black hover:bg-[#E0C3FC]'}`}
             >
               <CopyPlus className={`w-4 h-4 ${activeTab === 'batch-address-change' ? 'text-[#FF9000]' : 'text-black'}`} /> Lote Mudança
             </button>
             <button 
                onClick={() => setActiveTab('os')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'os' ? 'bg-[#5A189A] text-white shadow' : 'text-black hover:bg-[#E0C3FC]'}`}
             >
               <Wrench className={`w-4 h-4 ${activeTab === 'os' ? 'text-[#FF9000]' : 'text-black'}`} /> Gerador O.S.
             </button>
          </div>

          {/* Content Area - Using key={formVersion} to force component reset after generation */}
          <main key={formVersion}>
            {activeTab === 'individual' && <IndividualForm onGenerate={handleGenerate} />}
            {activeTab === 'batch' && <BatchProcessor onGenerateBatch={handleGenerate} />}
            {activeTab === 'pj' && <PJForm onGenerate={handleGeneratePJ} />}
            {activeTab === 'batch-pj' && <BatchPJProcessor onGenerateBatch={handleGeneratePJ} />}
            {activeTab === 'address-change' && <AddressChangeForm onGenerate={handleGenerateAddressChange} />}
            {activeTab === 'batch-address-change' && <BatchAddressChangeProcessor onGenerateBatch={handleGenerateAddressChange} />}
            {activeTab === 'os' && <OSGenerator />}
          </main>
        </div>

        {/* Helper for previewing print output on screen */}
        {(printData || pjPrintData || addressChangePrintData) && (
           <div className="mt-12 pt-8 border-t border-dashed border-gray-300">
              <div className="flex justify-center items-center gap-3 mb-4">
                 <h3 className="text-center text-gray-400 uppercase text-sm font-bold">Prévia de Impressão (Abaixo)</h3>
                 <Button 
                    onClick={() => window.print()} 
                    className="!py-1.5 !px-4 !text-xs !h-auto"
                 >
                    <Printer className="w-4 h-4" /> Imprimir Novamente
                 </Button>
                 <button 
                    onClick={() => setPreviewScale(prev => prev === 0.75 ? 1 : 0.75)}
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-white border border-gray-300 text-gray-600 text-xs font-medium hover:bg-gray-50 transition-colors shadow-sm h-[34px]"
                 >
                    {previewScale === 0.75 ? <ZoomIn className="w-3.5 h-3.5" /> : <ZoomOut className="w-3.5 h-3.5" />}
                    {previewScale === 0.75 ? "Zoom 100%" : "Zoom 75%"}
                 </button>
              </div>
              <div className="bg-gray-200 p-8 overflow-auto">
                <div 
                  className="mx-auto w-fit origin-top transition-transform duration-200"
                  style={{ transform: `scale(${previewScale})` }}
                >
                  {printData && printData.map((client, idx) => (
                    <div key={`pf-${idx}`}>
                       <TermoAdesao data={client} />
                       <TermoLocacao data={client} />
                    </div>
                  ))}
                  {pjPrintData && pjPrintData.map((client, idx) => (
                    <div key={`pj-${idx}`}>
                      <TermoAdesaoPJ data={client} />
                      <TermoLocacaoPJ data={client} />
                    </div>
                  ))}
                  {addressChangePrintData && addressChangePrintData.map((change, idx) => (
                    <MudancaEnderecoDoc key={`address-${idx}`} data={change} />
                  ))}
                </div>
              </div>
           </div>
        )}
      </div>

      {/* Print Container (Visible only during Print via CSS) */}
      <div id="print-container" style={{ display: 'none' }}>
        {printData && printData.map((client, idx) => (
          <React.Fragment key={`pf-${idx}`}>
            <TermoAdesao data={client} />
            <TermoLocacao data={client} />
          </React.Fragment>
        ))}
        {pjPrintData && pjPrintData.map((client, idx) => (
          <React.Fragment key={`pj-${idx}`}>
             <TermoAdesaoPJ data={client} />
             <TermoLocacaoPJ data={client} />
          </React.Fragment>
        ))}
        {addressChangePrintData && addressChangePrintData.map((change, idx) => (
             <MudancaEnderecoDoc key={`address-${idx}`} data={change} />
        ))}
      </div>
    </>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const extractClientDataWithAI = async (text: string) => {
  const ai = getAIInstance();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Extraia os dados do seguinte texto de atendimento de provedor de internet e retorne em JSON. 
    Se não encontrar um campo, deixe vazio. 
    Formatos esperados: CPF (000.000.000-00), RG (apenas números), Datas (AAAA-MM-DD).
    Planos de Internet válidos: ER-ENTRE 500, ER-ENTRE 600, ER-ENTRE 800, ER-ENTRE 920.

    Texto: ${text}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          nome: { type: Type.STRING },
          cpf: { type: Type.STRING },
          rg: { type: Type.STRING },
          tel1: { type: Type.STRING },
          email: { type: Type.STRING },
          endereco: { type: Type.STRING },
          bairro: { type: Type.STRING },
          cidade: { type: Type.STRING },
          planoInternet: { type: Type.STRING },
          valorInstalacao: { type: Type.STRING },
          formaPagamento: { type: Type.STRING },
          dataInstalacao: { type: Type.STRING },
        },
      },
    },
  });

  return JSON.parse(response.text);
};

export const extractPJDataWithAI = async (text: string) => {
  const ai = getAIInstance();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Extraia os dados de uma empresa (PJ) deste texto e retorne em JSON.
    Texto: ${text}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          razaoSocial: { type: Type.STRING },
          cnpj: { type: Type.STRING },
          inscricaoEstadual: { type: Type.STRING },
          endereco: { type: Type.STRING },
          cep: { type: Type.STRING },
          tel: { type: Type.STRING },
          planoEscolha: { type: Type.STRING },
          valorMensal: { type: Type.STRING },
          valorInstalacao: { type: Type.STRING },
          formaPagamento: { type: Type.STRING },
          fidelidade: { type: Type.STRING },
        },
      },
    },
  });

  return JSON.parse(response.text);
};

import React, { useState, useMemo } from 'react';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Select } from '../ui/Select';
import { ClientData, PlayhubApp } from '../../types';
import { PLAN_DETAILS, TV_PLANS, PLAYHUB_APPS } from '../../constants';
import { extractClientDataWithAI } from '../../services/aiService';
import { Printer, FileText, Check, PlayCircle, Search, Sparkles, Loader2, ClipboardPaste } from 'lucide-react';

interface Props {
  onGenerate: (data: ClientData) => void;
}

export const IndividualForm: React.FC<Props> = ({ onGenerate }) => {
  const [formData, setFormData] = useState<ClientData>({
    contrato: '',
    nome: '',
    rg: '',
    cpf: '',
    tel1: '',
    email: '',
    endereco: '',
    bairro: '',
    cidade: '',
    planoInternet: 'nenhum',
    planoTV: 'Nenhum',
    adicionais: [],
    apps: [],
    valorInstalacao: '',
    formaPagamento: '',
    dataInstalacao: '',
    isBatch: false
  });

  const [aiInput, setAiInput] = useState("");
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [appSearch, setAppSearch] = useState("");

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { id, value } = e.target;
    setFormData(prev => ({ ...prev, [id]: value }));
  };

  const handleAIAutoFill = async () => {
    if (!aiInput.trim()) return;
    setIsAiLoading(true);
    try {
      const data = await extractClientDataWithAI(aiInput);
      setFormData(prev => ({ ...prev, ...data }));
    } catch (error) {
      console.error("Erro na IA:", error);
      alert("Erro ao processar com IA. Tente preencher manualmente.");
    } finally {
      setIsAiLoading(false);
    }
  };

  const toggleApp = (appId: string) => {
    setFormData(prev => {
      const apps = prev.apps.includes(appId) 
        ? prev.apps.filter(id => id !== appId)
        : [...prev.apps, appId];
      return { ...prev, apps };
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.planoInternet === 'nenhum') {
      alert("Selecione um plano de internet");
      return;
    }
    onGenerate(formData);
  };

  const appsByCategory = useMemo(() => {
    const groups: Record<string, PlayhubApp[]> = {};
    PLAYHUB_APPS
      .filter(app => app.name.toLowerCase().includes(appSearch.toLowerCase()))
      .forEach(app => {
        if (!groups[app.category]) groups[app.category] = [];
        groups[app.category].push(app);
      });
    return groups;
  }, [appSearch]);

  const isComboEligible = formData.planoInternet.includes("800") || formData.planoInternet.includes("920");

  const CardHeader = ({ title, icon: Icon }: { title: string, icon?: React.ElementType }) => (
    <div className="bg-[#9D4EDD] p-4 rounded-t-lg flex items-center gap-2">
       {Icon && <Icon className="w-5 h-5 text-[#FF9000]" />}
       <h3 className="text-lg font-bold text-white">{title}</h3>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* AI Wizard Section */}
      <div className="bg-white border-2 border-dashed border-[#9D4EDD] rounded-lg p-4 shadow-sm">
        <div className="flex items-center gap-2 mb-3">
          <Sparkles className="w-5 h-5 text-[#9D4EDD]" />
          <h4 className="font-bold text-[#5A189A]">Preenchimento Inteligente (Gemini AI)</h4>
        </div>
        <textarea 
          className="w-full p-3 border border-gray-200 rounded-md text-sm mb-3 h-24 focus:ring-2 focus:ring-[#9D4EDD] focus:outline-none"
          placeholder="Cole qualquer texto aqui (ex: conversa de WhatsApp ou log do sistema) e a IA preencherá o formulário abaixo..."
          value={aiInput}
          onChange={(e) => setAiInput(e.target.value)}
        />
        <div className="flex justify-end">
          <Button 
            type="button" 
            onClick={handleAIAutoFill} 
            disabled={isAiLoading || !aiInput.trim()}
            className="!bg-[#9D4EDD] hover:!bg-[#7B2CBF]"
          >
            {isAiLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
            {isAiLoading ? "Processando..." : "Mágica: Preencher Formulário"}
          </Button>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="bg-[#F3E6FF] rounded-lg shadow-md border border-[#9D4EDD]">
          <CardHeader title="Dados do Cliente" icon={FileText} />
          <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-4">
            <Input id="contrato" label="Nº Contrato" value={formData.contrato} onChange={handleChange} required placeholder="Ex: 45530000" />
            <Input id="nome" label="Nome Completo" value={formData.nome} onChange={handleChange} required className="md:col-span-2" />
            <Input id="rg" label="RG" value={formData.rg} onChange={handleChange} />
            <Input id="cpf" label="CPF" value={formData.cpf} onChange={handleChange} required />
            <Input id="tel1" label="Telefone" value={formData.tel1} onChange={handleChange} />
            <Input id="email" label="E-mail" type="email" value={formData.email} onChange={handleChange} className="md:col-span-2" />
          </div>
        </div>

        <div className="bg-[#F3E6FF] rounded-lg shadow-md border border-[#9D4EDD]">
          <CardHeader title="Endereço" icon={MapPin} />
          <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-4">
            <Input id="endereco" label="Rua e Número" value={formData.endereco} onChange={handleChange} className="md:col-span-2" />
            <Input id="bairro" label="Bairro" value={formData.bairro} onChange={handleChange} />
            <Select 
              id="cidade" 
              label="Cidade" 
              value={formData.cidade} 
              onChange={handleChange}
              options={[
                { value: "", label: "Selecione..." },
                { value: "Rio das Ostras", label: "Rio das Ostras" },
                { value: "Casimiro de Abreu", label: "Casimiro de Abreu" },
                { value: "Cabo Frio", label: "Cabo Frio" }
              ]}
            />
          </div>
        </div>

        <div className="bg-[#F3E6FF] rounded-lg shadow-md border border-[#9D4EDD]">
          <CardHeader title="Planos e Serviços" />
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <Select 
              id="planoInternet" 
              label="Plano de Internet" 
              value={formData.planoInternet} 
              onChange={handleChange}
              options={[
                { value: "nenhum", label: "Selecione..." },
                ...Object.values(PLAN_DETAILS).map(p => ({ value: p.id, label: `${p.name} (R$ ${p.total.toFixed(2)})` }))
              ]}
            />
            <Select 
              id="planoTV" 
              label="Plano de TV" 
              value={formData.planoTV} 
              onChange={handleChange}
              options={Object.values(TV_PLANS).map(p => ({ value: p.id, label: p.label }))}
            />
          </div>
        </div>

        {/* ... Seção de Apps mantida igual ... */}
        <div className="bg-[#F3E6FF] rounded-lg shadow-md border border-[#9D4EDD]">
          <CardHeader title="Apps Playhub" icon={PlayCircle} />
          <div className="p-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
               <p className="text-sm text-gray-600">
                  Selecione os aplicativos incluídos no pacote. 
                  {isComboEligible && <span className="text-black font-bold ml-1"> (Preço Combo aplicado)</span>}
               </p>
               <div className="relative w-full md:w-64">
                  <Search className="absolute left-3 top-2.5 w-4 h-4 text-gray-400" />
                  <input 
                    type="text" 
                    placeholder="Buscar app..." 
                    className="w-full pl-9 pr-3 py-2 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-[#5A189A]"
                    value={appSearch}
                    onChange={(e) => setAppSearch(e.target.value)}
                  />
               </div>
            </div>

            <div className="space-y-6 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(appsByCategory).map(([category, apps]) => (
                <div key={category}>
                  <h4 className="text-sm font-bold text-black uppercase border-b border-[#9D4EDD] mb-3 pb-1">{category}</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                    {apps.map(app => {
                      const isSelected = formData.apps.includes(app.id);
                      const priceToDisplay = isComboEligible ? app.comboPrice : app.price;
                      return (
                        <div 
                          key={app.id}
                          onClick={() => toggleApp(app.id)}
                          className={`cursor-pointer border rounded-lg p-3 transition-all flex items-start gap-3 ${
                            isSelected ? 'bg-[#5A189A] border-[#5A189A] text-white shadow-md' : 'bg-white border-gray-200 text-gray-700 hover:border-[#9D4EDD]'
                          }`}
                        >
                          <div className={`w-5 h-5 rounded border flex items-center justify-center flex-shrink-0 mt-0.5 ${isSelected ? 'bg-white' : 'bg-white'}`}>
                            {isSelected && <Check className="w-3.5 h-3.5 text-[#5A189A]" />}
                          </div>
                          <div>
                            <div className="font-bold text-sm leading-tight">{app.name}</div>
                            <div className="text-xs mt-1 font-medium">R$ {priceToDisplay.toFixed(2).replace('.',',')}</div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="bg-[#F3E6FF] rounded-lg shadow-md border border-[#9D4EDD]">
          <CardHeader title="Financeiro" />
          <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-4">
            <Select 
              id="valorInstalacao" 
              label="Valor Instalação" 
              value={formData.valorInstalacao} 
              onChange={handleChange}
              options={[
                { value: "", label: "Selecione..." },
                { value: "Gratuita", label: "Gratuita" },
                { value: "R$140,00", label: "R$140,00" },
                { value: "R$500,00", label: "R$500,00" }
              ]}
            />
            <Select 
              id="formaPagamento" 
              label="Forma de Pagamento" 
              value={formData.formaPagamento} 
              onChange={handleChange}
              options={[
                { value: "", label: "Selecione..." },
                { value: "PIX", label: "PIX" },
                { value: "Cartão de Débito", label: "Cartão de Débito" },
                { value: "Cartão de Crédito", label: "Cartão de Crédito" }
              ]}
            />
            <Input id="dataInstalacao" label="Data da Instalação" type="date" value={formData.dataInstalacao} onChange={handleChange} />
          </div>
        </div>

        <div className="flex justify-end pt-4">
          <Button type="submit">
            <Printer className="w-4 h-4 text-[#FF9000]" />
            Gerar Documentos
          </Button>
        </div>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
