              </h3>
              {queue.length > 0 && (
                <button onClick={clearQueue} className="text-red-500 text-xs hover:underline font-medium">Limpar Tudo</button>
              )}
           </div>

           {queue.length === 0 ? (
             <div className="flex flex-col items-center justify-center h-64 text-gray-400">
