import React, { useState } from 'react';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Select } from '../ui/Select';
import { OSData } from '../../types';
import { parseCRMText } from '../../utils/parser';
import { Copy, Plus, Trash2 } from 'lucide-react';

interface Props {
  queue: OSData[];
  setQueue: React.Dispatch<React.SetStateAction<OSData[]>>;
  output: string;
  setOutput: React.Dispatch<React.SetStateAction<string>>;
}

export const OSGenerator: React.FC<Props> = ({ queue, setQueue, output, setOutput }) => {
  const [contrato, setContrato] = useState("");
  const [login, setLogin] = useState("");
  const [oco, setOco] = useState("");
  const [periodo, setPeriodo] = useState("Manhã");
  const [inputText, setInputText] = useState("");

  const handleAdd = () => {
    const parsed = parseCRMText(inputText);

    if (!contrato || !login || !oco || !parsed.nome) {
      alert("Preencha todos os campos obrigatórios (Contrato, Login, OCO, CRM Text).");
      return;
    }

    const newData: OSData = {
      contrato,
      login,
      oco,
      periodo,
      nome: parsed.nome || "N/A",
      referencia: parsed.referencia || "N/A",
      localizacao: parsed.localizacao || "N/A",
      formaPagamento: parsed.formaPagamento || "N/A"
    };

    setQueue(prev => [...prev, newData]);
    setContrato("");
    setLogin("");
    setOco("");
    setInputText("");
  };

  const handleGenerate = () => {
    const text = queue.map(data => `INSTALAÇÃO FTTH -
OCO: ${data.oco}
CONTRATO ${data.contrato}
LOGIN ${data.login}
REFERÊNCIA: ${data.referencia}
LOCALIZAÇÃO: ${data.localizacao}
INSTALAÇÃO: ${data.formaPagamento}
HORÁRIO: ${data.periodo}`).join('\n\n========================================\n\n');

    setOutput(text);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(output);
    alert("Copiado!");
  };

  const CardHeader = ({ title }: { title: string }) => (
    <div className="bg-[#9D4EDD] p-4 rounded-t-lg">
       <h3 className="text-lg font-bold text-white">{title}</h3>
    </div>
  );

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in duration-500">
      <div className="space-y-4">
         <div className="bg-[#F3E6FF] rounded-lg shadow-md border border-[#9D4EDD]">
            <CardHeader title="Adicionar O.S." />
            <div className="p-5">
              <div className="grid grid-cols-2 gap-4 mb-4">
                <Input label="Contrato" value={contrato} onChange={e => setContrato(e.target.value)} />
                <Input label="Login" value={login} onChange={e => setLogin(e.target.value)} />
                <Input label="OCO" value={oco} onChange={e => setOco(e.target.value)} className="col-span-2" />
                <Select 
                    label="Período" 
                    options={[{value: "Manhã", label: "Manhã"}, {value: "Tarde", label: "Tarde"}, {value: "Comercial", label: "Comercial"}]}
                    value={periodo}
                    onChange={e => setPeriodo(e.target.value)}
                    className="col-span-2"
                    id="os-periodo"
                />
              </div>
              <textarea 
                className="w-full p-2 border border-gray-300 rounded font-mono text-xs text-gray-900 mb-3 focus:outline-none focus:ring-2 focus:ring-[#5A189A]"
                rows={6}
                placeholder="Cole os dados do CRM aqui..."
                value={inputText}
                onChange={e => setInputText(e.target.value)}
              />
              <Button onClick={handleAdd} className="w-full">
                <Plus className="w-4 h-4 text-[#FF9000]"/> Adicionar
              </Button>
            </div>
         </div>

         <div className="bg-white p-4 rounded-lg border h-48 overflow-y-auto shadow-sm">
            <div className="flex justify-between mb-2 border-b pb-2">
               <h4 className="font-bold text-sm text-black">Fila ({queue.length})</h4>
               {queue.length > 0 && <button onClick={() => setQueue([])} className="text-red-500 text-xs">Limpar</button>}
            </div>
            <ul className="space-y-2">
               {queue.map((item, idx) => (
                  <li key={idx} className="bg-[#F3E6FF] p-2 rounded text-xs flex justify-between border border-[#9D4EDD]">
                     <span className="text-black font-medium">{item.nome} (OCO: {item.oco})</span>
                     <button onClick={() => setQueue(q => q.filter((_, i) => i !== idx))}><Trash2 className="w-3 h-3 text-gray-400 hover:text-red-500"/></button>
                  </li>
               ))}
            </ul>
         </div>
      </div>

      <div className="flex flex-col h-full">
         <Button onClick={handleGenerate} disabled={queue.length === 0} className="mb-4">Gerar Texto</Button>
         <textarea 
            readOnly
            className="w-full flex-grow p-4 bg-[#F3E6FF] font-mono text-sm rounded border border-[#9D4EDD] resize-none focus:outline-none text-black"
            value={output}
            placeholder="O resultado aparecerá aqui..."
         />
         <Button variant="secondary" onClick={copyToClipboard} disabled={!output} className="mt-4">
            <Copy className="w-4 h-4 text-[#FF9000]" /> Copiar Texto
         </Button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Select } from '../ui/Select';
import { PJData } from '../../types';
import { PJ_PLAN_DETAILS } from '../../constants';
import { Printer, Building2, MapPin, CreditCard } from 'lucide-react';

interface Props {
  onGenerate: (data: PJData) => void;
}

export const PJForm: React.FC<Props> = ({ onGenerate }) => {
  const [formData, setFormData] = useState<PJData>({
    origemContato: '',
    razaoSocial: '',
    nomeFantasia: '',
    cnpj: '',
    inscricaoEstadual: '',
    endereco: '',
    cep: '',
    referencia: '',
    localizacao: '',
    caixaPorta: '',
    socioTitular: '',
    dataNascimento: '',
    rg: '',
    cpf: '',
    tel: '',
    email: '',
    vencimento: '',
    planoEscolha: '',
    valorMensal: '',
    valorInstalacao: '',
    formaPagamento: '',
    fidelidade: '',
    multaRescisoria: '',
    dataGeracao: new Date().toISOString().split('T')[0]
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { id, value } = e.target;
    setFormData(prev => ({ ...prev, [id]: value }));
  };

  const handlePlanPresetChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const planId = e.target.value;
    if (!planId) return;

    const plan = PJ_PLAN_DETAILS[planId];
    if (plan) {
      setFormData(prev => ({
        ...prev,
        planoEscolha: plan.name,
        valorMensal: plan.total.toFixed(2).replace('.', ',')
      }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.razaoSocial || !formData.cnpj) {
      alert("Razão Social e CNPJ são obrigatórios.");
      return;
    }
    onGenerate(formData);
  };

  const CardHeader = ({ title, icon: Icon }: { title: string, icon?: React.ElementType }) => (
    <div className="bg-[#9D4EDD] p-4 rounded-t-lg flex items-center gap-2">
       {Icon && <Icon className="w-5 h-5 text-[#FF9000]" />}
       <h3 className="text-lg font-bold text-white">{title}</h3>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="bg-[#F3E6FF] rounded-lg shadow-md border border-[#9D4EDD]">
          <CardHeader title="Dados da Empresa" icon={Building2} />
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
            <Input id="razaoSocial" label="Razão Social" value={formData.razaoSocial} onChange={handleChange} required className="md:col-span-2" />
            <Input id="cnpj" label="CNPJ" value={formData.cnpj} onChange={handleChange} required />
            <Input id="inscricaoEstadual" label="Inscrição Estadual" value={formData.inscricaoEstadual} onChange={handleChange} />
            <Input id="tel" label="Telefone / Celular" value={formData.tel} onChange={handleChange} />
          </div>
        </div>

        <div className="bg-[#F3E6FF] rounded-lg shadow-md border border-[#9D4EDD]">
          <CardHeader title="Endereço" icon={MapPin} />
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
            <Input id="endereco" label="Endereço Completo" value={formData.endereco} onChange={handleChange} className="md:col-span-2" />
            <Input id="cep" label="CEP" value={formData.cep} onChange={handleChange} />
          </div>
        </div>

        <div className="bg-[#F3E6FF] rounded-lg shadow-md border border-[#9D4EDD]">
          <CardHeader title="Financeiro e Contrato" icon={CreditCard} />
          <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* Seletor de Planos Padrão */}
            <div className="md:col-span-3 mb-2">
               <Select 
                 label="Carregar Plano Padrão (Opcional)" 
                 id="planPreset"
                 options={[
                   { value: "", label: "Selecione para preencher automaticamente..." },
                   ...Object.values(PJ_PLAN_DETAILS).map(p => ({ 
                     value: p.id, 
                     label: `${p.name} - R$ ${p.total.toFixed(2).replace('.', ',')}` 
                   }))
                 ]}
                 onChange={handlePlanPresetChange}
               />
               <p className="text-[10px] text-gray-500 mt-1 pl-1">Selecionar um plano acima preencherá o "Plano Escolhido" e o "Valor Mensal" abaixo. Você ainda pode editar manualmente se necessário.</p>
            </div>

            <Input id="planoEscolha" label="Plano Escolhido" value={formData.planoEscolha} onChange={handleChange} className="md:col-span-2" />
            <Input id="valorMensal" label="Valor Mensal (R$)" value={formData.valorMensal} onChange={handleChange} required />
            <Input id="valorInstalacao" label="Valor Instalação" value={formData.valorInstalacao} onChange={handleChange} />
            <Input id="formaPagamento" label="Forma de Pagamento" value={formData.formaPagamento} onChange={handleChange} />
            <Input id="fidelidade" label="Fidelidade" value={formData.fidelidade} onChange={handleChange} />
            <Input id="dataGeracao" label="Data do Documento" type="date" value={formData.dataGeracao} onChange={handleChange} />
          </div>
        </div>

        <div className="flex justify-end pt-4">
          <Button type="submit">
            <Printer className="w-4 h-4 text-[#FF9000]" />
            Gerar Documentos PJ
          </Button>
        </div>
      </form>
    </div>
  );
};

